'use client';

import React from 'react';
import Link from 'next/link';
import { useParams, useRouter } from 'next/navigation';
import { ChevronLeft, Globe, Clock, AlertTriangle, ExternalLink, ShieldCheck, Mail, Webhook, Trash2 } from 'lucide-react';
import { useSiteDetail } from '@/hooks/useSiteDetail';
import { StatusBadge } from '@/components/StatusBadge';
import { CheckHistoryTable } from '@/components/CheckHistoryTable';
import { AlertChannelForm } from '@/components/AlertChannelForm';
import { Card } from '@/components/ui/Card';
import { formatRelativeTime } from '@/lib/utils';

export default function SiteDetailPage() {
  const params = useParams();
  const router = useRouter();
  const siteId = params.siteId as string;

  const {
    site,
    isLoading,
    checks,
    activeIncident,
    uptime24h,
    uptime7d,
    channels,
    addChannel,
    deleteChannel,
  } = useSiteDetail(siteId);

  if (isLoading) {
    return (
      <div className="space-y-6 animate-pulse">
        <div className="h-6 w-32 bg-[#161B22] rounded" />
        <div className="h-40 bg-[#161B22] rounded-lg border border-[#30363D]" />
        <div className="h-24 bg-[#161B22] rounded-lg border border-[#30363D]" />
      </div>
    );
  }

  if (!site) {
    return (
      <div className="text-center py-20">
        <h2 className="text-lg font-semibold text-white">Monitored Site Not Found</h2>
        <p className="text-xs text-[#8B949E] mt-1 mb-4">
          The requested site ID does not exist or you do not have permission to view it.
        </p>
        <Link
          href="/dashboard"
          className="text-xs font-mono text-[#00FF87] hover:underline"
        >
          &larr; Return to Dashboard
        </Link>
      </div>
    );
  }

  const getUptimeColor = (pct: number) => {
    if (pct >= 99) return 'text-[#00FF87]';
    if (pct >= 95) return 'text-[#F0A500]';
    return 'text-[#FF4D4F]';
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-300">
      {/* Navigation & Header */}
      <div>
        <Link
          href="/dashboard"
          className="inline-flex items-center gap-1 text-xs font-mono text-[#8B949E] hover:text-white transition-colors mb-3"
        >
          <ChevronLeft className="h-3.5 w-3.5" /> Back to All Monitors
        </Link>

        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-[#30363D] pb-6">
          <div>
            <div className="flex items-center gap-3">
              <h1 className="text-2xl font-bold tracking-tight text-white">{site.name}</h1>
              <StatusBadge status={site.last_status} />
            </div>
            <div className="flex items-center gap-2 mt-1.5 text-xs text-[#8B949E] font-mono">
              <Globe className="h-3.5 w-3.5" />
              <span>{site.url}</span>
              <a
                href={site.url}
                target="_blank"
                rel="noreferrer"
                className="hover:text-white transition-colors ml-1"
              >
                <ExternalLink className="h-3 w-3" />
              </a>
              <span className="text-[#30363D]">&bull;</span>
              <span>Checked every {site.check_interval_s}s</span>
            </div>
          </div>
        </div>
      </div>

      {/* Active Incident Warning Block if currently down */}
      {activeIncident && (
        <div className="p-5 rounded-lg bg-[#FF4D4F]/10 border border-[#FF4D4F]/50 shadow-lg">
          <div className="flex items-start gap-3">
            <div className="p-2 rounded bg-[#FF4D4F]/20 text-[#FF4D4F]">
              <AlertTriangle className="h-5 w-5" />
            </div>
            <div>
              <h3 className="text-base font-semibold text-[#FF4D4F]">
                Active Downtime Incident in Progress
              </h3>
              <div className="mt-2 space-y-1 text-xs text-[#E6EDF3] font-mono">
                <div>Started: {new Date(activeIncident.started_at).toUTCString()}</div>
                {activeIncident.root_cause && (
                  <div className="text-[#FF7B72]">Cause: {activeIncident.root_cause}</div>
                )}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Uptime Statistics Row */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card className="p-4">
          <span className="text-xs text-[#8B949E] uppercase tracking-wider block font-mono">
            Uptime (Last 24h)
          </span>
          <span className={`text-3xl font-bold font-mono mt-1 block ${getUptimeColor(uptime24h)}`}>
            {uptime24h}%
          </span>
        </Card>

        <Card className="p-4">
          <span className="text-xs text-[#8B949E] uppercase tracking-wider block font-mono">
            Uptime (Last 7 Days)
          </span>
          <span className={`text-3xl font-bold font-mono mt-1 block ${getUptimeColor(uptime7d)}`}>
            {uptime7d}%
          </span>
        </Card>

        <Card className="p-4">
          <span className="text-xs text-[#8B949E] uppercase tracking-wider block font-mono">
            Latest Latency
          </span>
          <span className="text-3xl font-bold font-mono text-white mt-1 block">
            {checks[0]?.response_ms !== undefined && checks[0]?.response_ms !== null
              ? `${checks[0].response_ms} ms`
              : '—'}
          </span>
        </Card>

        <Card className="p-4">
          <span className="text-xs text-[#8B949E] uppercase tracking-wider block font-mono">
            Last Checked
          </span>
          <span className="text-lg font-bold font-mono text-white mt-2 block">
            {formatRelativeTime(site.last_checked_at)}
          </span>
        </Card>
      </div>

      {/* Check History Section */}
      <div className="space-y-3">
        <div className="flex items-center justify-between">
          <h2 className="text-lg font-semibold text-white">Check History</h2>
          <span className="text-xs font-mono text-[#8B949E]">
            Showing latest {checks.length} health checks
          </span>
        </div>
        <CheckHistoryTable checks={checks} />
      </div>

      {/* Alert Channels Section */}
      <div className="space-y-4 pt-4 border-t border-[#30363D]">
        <div className="flex items-center justify-between">
          <div>
            <h2 className="text-lg font-semibold text-white">Alert Channels</h2>
            <p className="text-xs text-[#8B949E]">
              Notifications dispatched when this site goes down or recovers.
            </p>
          </div>
          <AlertChannelForm siteId={site.id} onAddChannel={addChannel} />
        </div>

        {channels.length === 0 ? (
          <div className="p-6 rounded-lg border border-[#30363D] bg-[#161B22]/40 text-center">
            <p className="text-xs text-[#8B949E]">
              No site-specific channels configured. Global alert channels in Settings will receive notifications.
            </p>
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            {channels.map((chan) => (
              <div
                key={chan.id}
                className="p-3.5 rounded-lg border border-[#30363D] bg-[#161B22] flex items-center justify-between"
              >
                <div className="flex items-center gap-2.5">
                  {chan.channel_type === 'email' ? (
                    <Mail className="h-4 w-4 text-[#00FF87]" />
                  ) : (
                    <Webhook className="h-4 w-4 text-[#58A6FF]" />
                  )}
                  <div>
                    <span className="text-xs font-mono text-white block">
                      {chan.config?.email || chan.config?.url}
                    </span>
                    <span className="text-[10px] text-[#8B949E] uppercase font-mono">
                      {chan.channel_type} alert
                    </span>
                  </div>
                </div>

                <button
                  type="button"
                  onClick={() => deleteChannel(chan.id)}
                  className="p-1 text-[#8B949E] hover:text-[#FF4D4F] rounded transition-colors"
                  title="Remove channel"
                >
                  <Trash2 className="h-3.5 w-3.5" />
                </button>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
